import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { Alert, TabInfo, TabsWithFilters } from 'components';
import { useGlobalDataAvailability } from 'contexts';
import { useRelatedAnalysisContextBanner } from 'hooks';
import { brandPowerBookVisibleFilters } from 'pages/constants';
import { createTab } from 'utils/tab';

import { BRAND_POWER_BOOK_PATH } from './constants';
import { PowerBook } from './tabs';

export const BRAND_POWER_BOOK_PAGE_NAME = 'portfolio-brand_brand-power-results';

export const BrandPowerBook: React.FC = () => {
  const { formatMessage } = useIntl();
  const { shouldShowGlobalBanner } = useGlobalDataAvailability();
  const showRelatedAnalysisBanner =
    useRelatedAnalysisContextBanner('performance-tool');
  const showGlobalDataBanner = shouldShowGlobalBanner('power');

  const tabs = useMemo<TabInfo[]>(
    () => [
      createTab(
        'power-book',
        'Overview',
        <PowerBook
          dataTestId="tabpanel-power-book"
          isOpenedFromPerformanceToolContext={showRelatedAnalysisBanner}
        />,
        false,
      ),
    ],
    [showRelatedAnalysisBanner],
  );

  return (
    <TabsWithFilters
      dataTestId="brand-power-book"
      filter={{
        pageName: BRAND_POWER_BOOK_PAGE_NAME,
        visibleFields: brandPowerBookVisibleFilters,
      }}
      tabConfig={{
        tabs,
        baseRoute: BRAND_POWER_BOOK_PATH,
      }}
      breadcrumbsList={[
        {
          href: '/portfolio-brand',
          pageName: formatMessage({ id: 'Pillars.pageName.portfolioBrand' }),
        },
        {
          href: BRAND_POWER_BOOK_PATH,
          pageName: formatMessage({ id: 'Sidebar.brandPowerBook' }),
        },
      ]}
      bannerContent={
        showGlobalDataBanner ? (
          <>
            {showGlobalDataBanner && (
              <Alert
                type="warning"
                position="inline"
                title={formatMessage({ id: 'GlobalData.bannerTitle' })}
                message={formatMessage({ id: 'GlobalData.bannerMessage' })}
                dataTestId="global-data-banner-power"
              />
            )}
          </>
        ) : null
      }
    />
  );
};
